-- Modify "seller_response_drafts" table
ALTER TABLE "procurement"."seller_response_drafts" DROP CONSTRAINT "seller_response_drafts_payload_check", ADD CONSTRAINT "seller_response_drafts_payload_check" CHECK ((jsonb_typeof(payload) = 'object'::text) AND (octet_length((payload)::text) <= 16384));
-- Modify "seller_response_versions" table
ALTER TABLE "procurement"."seller_response_versions" DROP COLUMN "outside_buyer_requested_range";
-- Modify "seller_responses" table
ALTER TABLE "procurement"."seller_responses" ADD CONSTRAINT "seller_responses_withdrawn_reason_code_check" CHECK ((withdrawn_reason_code IS NULL) OR ((char_length(withdrawn_reason_code) >= 1) AND (char_length(withdrawn_reason_code) <= 64) AND (withdrawn_reason_code !~ '^[\u0009\u000a\u000b\u000c\u000d\u0020\u0085\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000]|[\u0009\u000a\u000b\u000c\u000d\u0020\u0085\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000]$'::text))), ADD CONSTRAINT "seller_responses_withdrawn_reason_pair" CHECK ((withdrawn_reason_code IS NULL) OR (withdrawn_version IS NOT NULL)), ADD CONSTRAINT "seller_responses_write_closed_reason_code_check" CHECK ((write_closed_reason_code IS NULL) OR ((char_length(write_closed_reason_code) >= 1) AND (char_length(write_closed_reason_code) <= 64) AND (write_closed_reason_code !~ '^[\u0009\u000a\u000b\u000c\u000d\u0020\u0085\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000]|[\u0009\u000a\u000b\u000c\u000d\u0020\u0085\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000]$'::text))), ADD CONSTRAINT "seller_responses_write_closed_reason_pair" CHECK ((write_closed_reason_code IS NULL) OR (write_closed_reason IS NOT NULL)), ADD COLUMN "withdrawn_reason_code" text NULL, ADD COLUMN "write_closed_reason_code" text NULL;
